// tokenize.js must split text exactly like the Python reference (texts.py).
// chunks.json is generated by `llmsimbench export-web`.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { test } from "node:test";

import { charsPerToken, chunkText, guessLang } from "../js/tokenize.js";

const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
const golden = JSON.parse(read("./chunks.json"));
const presets = JSON.parse(read("../data/presets.json"));
const manifest = JSON.parse(read("../data/texts/manifest.json"));
const textOf = (id) => read(`../data/texts/${manifest.texts.find((x) => x.id === id).file}`);
const digest = (pieces) => createHash("sha256").update(pieces.join("\u0000"), "utf8").digest("hex");

test("chunkText matches Python on edge cases", () => {
  for (const c of golden.chunks.filter((x) => "pieces" in x)) {
    assert.deepEqual(chunkText(c.text, c.chars_per_token), c.pieces,
                     `${JSON.stringify(c.text)} at ${c.chars_per_token}`);
  }
});

test("chunkText and charsPerToken match Python on every text and tokenizer", () => {
  const cases = golden.chunks.filter((x) => "text_id" in x);
  assert.ok(cases.length >= manifest.texts.length);
  for (const c of cases) {
    const what = `${c.text_id} ${c.family} ${c.role ?? ""}${c.turn ?? ""}`;
    assert.deepEqual(charsPerToken(presets.tokenizers, c.text_id, c.family),
                     { value: c.chars_per_token, measured: c.measured }, what);
    const raw = textOf(c.text_id);
    const text = c.turn === null ? raw : JSON.parse(raw).turns[c.turn][c.role];
    const pieces = chunkText(text, c.chars_per_token);
    assert.equal(pieces.length, c.count, what);
    assert.deepEqual(pieces.slice(0, c.head.length), c.head, what);
    assert.equal(digest(pieces), c.sha256, what);
  }
});

test("guessLang matches Python", () => {
  for (const c of golden.guess_lang) {
    const text = "text_id" in c ? textOf(c.text_id) : c.text;
    assert.equal(guessLang(text), c.lang, JSON.stringify(c.text ?? c.text_id));
  }
});
